{
  "scenario": "deffuant",
  "phenomenon": "Opinion formation and adaptive network rewiring under bounded confidence and backfire",
  "indicators": [
    {
      "id": "micro_interaction_distance_mean",
      "semantic_name": "Mean sampled interaction opinion distance",
      "scientific_definition": "Time series of the average absolute opinion distance across all sampled agent interactions at each step.",
      "phenomenon": "Opinion-distance interaction selection",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "sampled agent interactions",
      "source_fields": [
        "interaction_distance"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "field",
          "name": "interaction_distance"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Captures the typical proximity of sampled encounters, relevant to confidence thresholds for assimilation and backfire."
    },
    {
      "id": "micro_interaction_distance_std",
      "semantic_name": "Standard deviation of sampled interaction opinion distance",
      "scientific_definition": "Time series of the standard deviation of absolute opinion distances across sampled interactions at each step.",
      "phenomenon": "Opinion-distance interaction selection",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "sampled agent interactions",
      "source_fields": [
        "interaction_distance"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "field",
          "name": "interaction_distance"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Measures heterogeneity in encounter opinion distance across interactions, reflecting the diversity of local sampled ties."
    },
    {
      "id": "micro_interaction_distance_q90",
      "semantic_name": "90th percentile sampled interaction opinion distance",
      "scientific_definition": "Time series of the 90th percentile of absolute opinion distances across sampled interactions at each step.",
      "phenomenon": "Opinion-distance interaction selection",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "sampled agent interactions",
      "source_fields": [
        "interaction_distance"
      ],
      "computation": {
        "op": "quantile",
        "input": {
          "op": "field",
          "name": "interaction_distance"
        },
        "axis": "agent",
        "q": 0.9
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Highlights the upper tail of sampled opinion distances, which is where backfire and rejection events are concentrated."
    },
    {
      "id": "micro_assimilation_rate",
      "semantic_name": "Assimilation acceptance rate",
      "scientific_definition": "Time series of the fraction of sampled interactions that match the assimilation condition in each step.",
      "phenomenon": "Bounded-confidence assimilation",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "sampled agent interactions",
      "source_fields": [
        "interaction_accepted"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "interaction_accepted"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "confidence_bound",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "A larger confidence bound admits a broader set of sampled opinion distances, increasing the fraction of interactions classified as accepted."
        }
      ],
      "scientific_rationale": "Provides a direct micro-level measure of the prevalence of successful assimilation encounters under the current confidence threshold."
    },
    {
      "id": "micro_backfire_rate",
      "semantic_name": "Backfire-triggered interaction rate",
      "scientific_definition": "Time series of the fraction of sampled interactions that trigger the repulsive backfire condition in each step.",
      "phenomenon": "Backfire-driven opinion repulsion",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "sampled agent interactions",
      "source_fields": [
        "interaction_backfire"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "interaction_backfire"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "backfire_threshold",
          "relationship": "direct",
          "expected_indicator_direction": "decrease",
          "rationale": "A higher backfire threshold removes borderline large-distance encounters from the repulsive regime, lowering the backfire trigger rate."
        }
      ],
      "scientific_rationale": "Directly tracks the frequency of repulsive events that can push opinions apart and trigger adaptive rewiring."
    },
    {
      "id": "micro_rejection_rate",
      "semantic_name": "Rejected interaction rate",
      "scientific_definition": "Time series of the fraction of sampled interactions that are neither assimilating nor backfire events in each step.",
      "phenomenon": "Rejection and failed influence",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "sampled agent interactions",
      "source_fields": [
        "interaction_rejected"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "interaction_rejected"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Measures the share of interactions that produce no opinion update, capturing the middle-distance rejection regime between assimilation and backfire."
    },
    {
      "id": "micro_rewiring_rate",
      "semantic_name": "Adaptive rewiring rate",
      "scientific_definition": "Time series of the fraction of focal agents whose sampled rejected or backfire tie was successfully rewired in each step.",
      "phenomenon": "Adaptive network restructuring",
      "scale": "micro",
      "entity_scope": "interaction",
      "entities": "sampled agent interactions",
      "source_fields": [
        "edge_rewired"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "edge_rewired"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Captures the micro-level frequency of successful network tie replacement following rejected or backfire encounters."
    },
    {
      "id": "micro_mean_abs_agent_shift",
      "semantic_name": "Mean absolute opinion update magnitude",
      "scientific_definition": "Time series of the mean absolute signed opinion update applied to agents at each step.",
      "phenomenon": "Opinion update intensity",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "agent_shift"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "abs",
          "input": {
            "op": "field",
            "name": "agent_shift"
          }
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "assimilation_strength",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "Assimilation_strength scales the portion of partner difference applied during accepted assimilation updates, increasing the average absolute shift."
        }
      ],
      "scientific_rationale": "Provides a direct micro-level summary of how strongly individual opinions move during updates."
    },
    {
      "id": "micro_agent_shift_std",
      "semantic_name": "Standard deviation of opinion update magnitude",
      "scientific_definition": "Time series of the standard deviation of signed opinion updates across agents at each step.",
      "phenomenon": "Opinion update intensity",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "agent_shift"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "field",
          "name": "agent_shift"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Measures heterogeneity in update intensity across agents, reflecting uneven exposure to assimilating or backfire encounters."
    },
    {
      "id": "micro_opinion_mean",
      "semantic_name": "Mean individual opinion",
      "scientific_definition": "Time series of the mean opinion across all individual agents before each step update.",
      "phenomenon": "Opinion state distribution",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "state_opinion"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "field",
          "name": "state_opinion"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Summarizes the central tendency of individual opinions, even though it is produced by aggregating across individual micro states."
    },
    {
      "id": "micro_opinion_std",
      "semantic_name": "Standard deviation of individual opinions",
      "scientific_definition": "Time series of the standard deviation of opinion values across all individual agents before each step update.",
      "phenomenon": "Opinion state distribution",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "state_opinion"
      ],
      "computation": {
        "op": "std",
        "input": {
          "op": "field",
          "name": "state_opinion"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Measures opinion dispersion across individuals, a core micro-level prerequisite for consensus, polarization, or clustering."
    },
    {
      "id": "micro_abs_opinion_mean",
      "semantic_name": "Mean absolute individual opinion",
      "scientific_definition": "Time series of the mean absolute opinion across all individual agents before each step update.",
      "phenomenon": "Opinion state distribution",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "state_opinion"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "abs",
          "input": {
            "op": "field",
            "name": "state_opinion"
          }
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Tracks overall opinion extremity irrespective of sign, complementing signed central tendency measures."
    },
    {
      "id": "micro_extreme_opinion_fraction",
      "semantic_name": "Fraction of extreme individual opinions",
      "scientific_definition": "Time series of the fraction of agents with absolute opinion at least 0.75 before each step update.",
      "phenomenon": "Extreme opinion state",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "state_opinion"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "greater_equal",
          "left": {
            "op": "abs",
            "input": {
              "op": "field",
              "name": "state_opinion"
            }
          },
          "right": {
            "op": "constant",
            "value": 0.75
          }
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Detects the prevalence of strongly polarized individual opinions, a micro-level signature of opinion clustering."
    },
    {
      "id": "micro_sign_flip_rate",
      "semantic_name": "Opinion sign-flip rate",
      "scientific_definition": "Time series of the fraction of agents whose opinion update crosses zero at each step.",
      "phenomenon": "Opinion sign crossing",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "individual sign-crossing events",
      "source_fields": [
        "sign_flip"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "sign_flip"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Counts rare elementary events where updates move an individual across the opinion zero boundary, indicating large directional shifts."
    },
    {
      "id": "micro_opinion_entropy",
      "semantic_name": "Binned entropy of individual opinions",
      "scientific_definition": "Time series of binned entropy of opinion values across agents, using 10 bins over the bounded opinion range.",
      "phenomenon": "Opinion state distribution",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "state_opinion"
      ],
      "computation": {
        "op": "binned_entropy",
        "input": {
          "op": "field",
          "name": "state_opinion"
        },
        "axis": "agent",
        "bins": 10
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Quantifies the diversity of individual opinions; high entropy indicates broad spread, low entropy indicates consensus or tight clustering."
    },
    {
      "id": "micro_agent_shift_entropy",
      "semantic_name": "Binned entropy of individual opinion updates",
      "scientific_definition": "Time series of binned entropy of signed opinion updates across agents, using 10 bins.",
      "phenomenon": "Opinion update intensity",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "individual agents",
      "source_fields": [
        "agent_shift"
      ],
      "computation": {
        "op": "binned_entropy",
        "input": {
          "op": "field",
          "name": "agent_shift"
        },
        "axis": "agent",
        "bins": 10
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [],
      "scientific_rationale": "Measures the diversity of update magnitudes across individuals, reflecting heterogeneous influence exposure at the micro level."
    }
  ],
  "interpretation_boundary": "Phase A only: these indicators are executable observables derived from public simulator semantics. They are descriptive and not causal, statistical, or predictive claims. No relationships, candidate edges, mechanism paths, or prospective predictions are inferred."
}
